// IHarvestNG.dll entry point. SKSEPluginInfo (AE) / SKSEPlugin_Query (SE, VR) are generated by
// add_commonlibsse_plugin() in CMake; only SKSEPluginLoad lives here.

#include "Events.h"
#include "Forms.h"
#include "Hooks.h"
#include "Log.h"
#include "Manager.h"
#include "Placements.h"
#include "Serialization.h"
#include "Settings.h"
#include "UI/Menu.h"

#include <IHarvestNG/Version.h>

namespace
{
	std::string_view RuntimeName()
	{
		switch (REL::Module::GetRuntime()) {
		case REL::Module::Runtime::AE:
			return "AE"sv;
		case REL::Module::Runtime::SE:
			return "SE"sv;
		case REL::Module::Runtime::VR:
			return "VR"sv;
		default:
			return "Unknown"sv;
		}
	}

	void OnSKSEMessage(SKSE::MessagingInterface::Message* a_msg)
	{
		switch (a_msg->type) {
		case SKSE::MessagingInterface::kPostLoad:
			ihng::ui::Register();
			break;
		case SKSE::MessagingInterface::kDataLoaded:
			ihng::Forms::Get().CheckWorldOverrides();
			if (ihng::Forms::Get().Resolve()) {
				ihng::placements::Resolve(ihng::Forms::Get().pluginName);
				ihng::events::Register();
			}
			break;
		case SKSE::MessagingInterface::kPostLoadGame:
		case SKSE::MessagingInterface::kNewGame:
			if (static bool warned = false; !warned && !ihng::Forms::Get().WorldOverrideWarning().empty()) {
				warned = true;  // once per game launch
				RE::DebugMessageBox(ihng::Forms::Get().WorldOverrideWarning().c_str());
			}
			ihng::Manager::GetSingleton().QueueTask([] { ihng::Manager::GetSingleton().OnPostLoad(); });
			break;
		default:
			break;
		}
	}
}

SKSEPluginLoad(const SKSE::LoadInterface* a_skse)
{
	SKSE::Init(a_skse, { .log = false });

	const bool logOk = ihng::log::Init();
	auto&      settings = ihng::Settings::GetSingleton();
	settings.Load();
	ihng::log::SetLevel(settings.Get().logLevel);

	logger::info("{} v{} loading on Skyrim {} {}", ihng::version::kName, ihng::version::kString, RuntimeName(),
		REL::Module::get().version().string());
	if (!logOk) {
		logger::warn("Could not resolve the SKSE log directory");
	}

	if (!ihng::hooks::Install()) {
		return true;  // stay loaded but inert; the log says why
	}
	ihng::serialization::Register();

	if (!SKSE::GetMessagingInterface()->RegisterListener(OnSKSEMessage)) {
		logger::critical("Failed to register the SKSE messaging listener");
		return false;
	}
	logger::info("{} loaded", ihng::version::kName);
	return true;
}
